149	    if (productIds.length > 0) {
150	      try {
151	        aiConfigs = await this.prisma.productAIConfig.findMany({
152	          take: 50,
153	          where: { productId: { in: productIds } },
154	          select: {
155	            id: true,
156	            productId: true,
157	            tone: true,
158	            persistenceLevel: true,
159	            messageLimit: true,
160	            customerProfile: true,
161	            positioning: true,
162	            objections: true,
163	            salesArguments: true,
164	          },
165	        });
166	      } catch {
167	        /* ProductAIConfig may not exist yet */
168	      }
169	    }
170	
171	    const compressedContext = await this.ctx.buildAndPersistCompressedContext(
172	      workspaceId,
173	      contactId,
174	      phone,
175	      contact,
176	    );
177	    const tacticalHint = this.ctx.buildLeadTacticalHint({
178	      leadName: this.ctx.isRecord(contact) ? this.ctx.readText(contact.name).trim() : '',
179	      currentMessage: message,
