183	    // 2. Build system prompt and style instruction
184	    const agentRuntimeContext = await this.buildAgentRuntimeContext({
185	      workspaceId,
186	      channel: this.ctx.readText(context?.channel, 'whatsapp'),
187	      message,
188	      contactId,
189	      ...(params.allowedTools !== undefined ? { allowedTools: params.allowedTools } : {}),
190	    });
191	    const systemPrompt = [
192	      this.ctx.buildSystemPrompt(workspace, products, aiConfigs),
193	      agentRuntimeContext.systemPromptBlock,
194	    ].join('\n\n');
