488	        const paymentAmount = this.num(args.amount);
489	        if (this.riskGate && paymentAmount > 0) {
490	          const gateDecision = this.riskGate.gatePaymentAction({
491	            amountCents: paymentAmount,
492	            reversible: true,
493	            target: 'lead',
494	          });
495	          if (gateDecision.verdict === 'block') {
496	            this.logger.error(
497	              `R4 BLOCKED: create_payment_link — ${gateDecision.reason}`,
498	            );
499	            return {
500	              success: false,
501	              blocked: true,
502	              riskClass: gateDecision.classification.class,
503	              error: gateDecision.reason,
504	            };
505	          }
506	          if (gateDecision.verdict === 'warn') {
507	            this.logger.warn(
