540	        return result;
541	      }
542	      case 'update_lead_status':
543	        return this.actions.actionUpdateLeadStatus(workspaceId, contactId, args);
544	      case 'add_tag':
545	        return this.actions.actionAddTag(workspaceId, contactId, args);
546	      case 'schedule_followup':
