import { Injectable, Optional } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { StructuredLogger } from '../logging/structured-logger';
import OpenAI from 'openai';
import { PlanLimitsService } from '../billing/plan-limits.service';
import { AuditService } from '../audit/audit.service';
import { createTextLlmClient } from '../lib/llm-provider';
import { resolveBackendOpenAIModel } from '../lib/openai-models';
import { PrismaService } from '../prisma/prisma.service';
import { chatCompletionWithFallback } from './openai-wrapper';
import { UnifiedAgentContextService } from './unified-agent-context.service';
import { UnifiedAgentResponseService } from './unified-agent-response.service';
import { UnifiedAgentActionsService } from './unified-agent-actions.service';
import { AgentRuntimeContextService } from './agent-runtime';
import { AbiBuilderService } from './abi/abi-builder.service';
import { RiskGateService } from './risk-class/risk-gate.service';
export type { ToolArgs, ActionEntry } from './unified-agent.types';
import type { ToolArgs, ActionEntry, PredecidedAction } from './unified-agent.types';
import {
  buildPredecidedActionDraft,
  executePredecidedAgentActions,
} from './unified-agent-predecided-actions.part';
import {
  buildUnifiedAgentMessageContext,
  type UnknownRecord,
} from './unified-agent-message-context.part';
import { executeUnifiedAgentToolCalls } from './unified-agent-tool-calls.part';
import {
  executeUnifiedAgentToolAction,
  unifiedAgentActionSucceeded,
} from './unified-agent-tool-router.part';

const UNIFIED_AGENT_PROVIDER_CONFIG_REQUIRED =
  'Primary LLM configuration is required for unified agent generation';

/**
 * KLOEL Unified Agent Service — orchestrator.
 *
 * This service coordinates context loading, LLM calls, tool dispatch, and
 * response composition. All heavy logic lives in the sub-services injected
 * here. The constructor, processMessage, and executeToolAction router are the
 * only concerns of this file.
 */
/** Idempotency: enforced at HTTP layer via @Idempotent() guard + Stripe idempotencyKey. */
@Injectable()
export class UnifiedAgentService {
  private readonly logger = StructuredLogger.from(UnifiedAgentService.name);
  private readonly openai: OpenAI | null;
  private readonly primaryBrainModel: string;
  private readonly fallbackBrainModel: string;
  private readonly writerModel: string;
  private readonly fallbackWriterModel: string;

  constructor(
    private readonly prisma: PrismaService,
    private readonly config: ConfigService,
    private readonly planLimits: PlanLimitsService,
    private readonly auditService: AuditService,
    private readonly ctx: UnifiedAgentContextService,
    private readonly response: UnifiedAgentResponseService,
    private readonly actions: UnifiedAgentActionsService,
    @Optional() private readonly agentRuntime?: AgentRuntimeContextService,
    @Optional() private readonly abiBuilder?: AbiBuilderService,
    @Optional() private readonly riskGate?: RiskGateService,
  ) {
    this.openai = createTextLlmClient(this.config);
    this.primaryBrainModel = resolveBackendOpenAIModel('brain', this.config);
    this.fallbackBrainModel = resolveBackendOpenAIModel('brain_fallback', this.config);
    this.writerModel = resolveBackendOpenAIModel('writer', this.config);
    this.fallbackWriterModel = resolveBackendOpenAIModel('writer_fallback', this.config);
  }

  async processIncomingMessage(params: {
    workspaceId: string;
    phone: string;
    message: string;
    contactId?: string;
    channel?: string;
    context?: UnknownRecord;
    executeTools?: boolean;
  }): Promise<{
    reply?: string;
    response?: string;
    actions: ActionEntry[];
    intent: string;
    confidence: number;
  }> {
    const result = await this.processMessage({
      workspaceId: params.workspaceId,
      contactId: params.contactId || '',
      phone: params.phone,
      message: params.message,
      context: {
        channel: params.channel || 'whatsapp',
        executeTools: params.executeTools !== false,
        ...(params.context || {}),
      },
    });

    return {
      actions: result.actions,
      intent: result.intent,
      confidence: result.confidence,
      ...(result.response !== undefined
        ? { reply: result.response, response: result.response }
        : {}),
    };
  }

  async processMessage(params: {
    allowedTools?: string[];
    predecidedActions?: PredecidedAction[];
    workspaceId: string;
    contactId: string;
    phone: string;
    message: string;
    context?: UnknownRecord;
  }): Promise<{
    actions: ActionEntry[];
    response?: string;
    intent: string;
    confidence: number;
  }> {
    const { workspaceId, contactId, phone, message, context } = params;

    const predecidedActions = params.predecidedActions ?? [];

    if (!this.openai && predecidedActions.length === 0) {
      this.logger.warn('OpenAI not configured');
      return this.response.buildFallbackResult(message);
    }

    const messageContext = await buildUnifiedAgentMessageContext({
      prisma: this.prisma,
      ctx: this.ctx,
      response: this.response,
      logger: this.logger,
      ...(this.agentRuntime !== undefined ? { agentRuntime: this.agentRuntime } : {}),
      ...(this.abiBuilder !== undefined ? { abiBuilder: this.abiBuilder } : {}),
      ...(params.allowedTools !== undefined ? { allowedTools: params.allowedTools } : {}),
      ...(context !== undefined ? { context } : {}),
      workspaceId,
      contactId,
      phone,
      message,
    });
    const { messages, historyTurns, channel } = messageContext;

    if (predecidedActions.length > 0) {
      const actionsList = await executePredecidedAgentActions({
        ...(params.allowedTools !== undefined ? { allowedTools: params.allowedTools } : {}),
        contactId,
        ...(context !== undefined ? { context } : {}),
        executeTool: this.executeToolAction.bind(this),
        logAutopilotEvent: this.actions.logAutopilotEvent.bind(this.actions),
        phone,
        predecidedActions,
        workspaceId,
      });
      const intent = this.response.extractIntent(actionsList, message);
      const draftedReply = await this.response.composeWriterReply(
        this.openai,
        this.writerModel,
        this.fallbackWriterModel,
        {
          workspaceId,
          customerMessage: message,
          assistantDraft: buildPredecidedActionDraft(actionsList),
          actions: actionsList,
          historyTurns,
        },
      );

      await this.agentRuntime?.recordTurnOutcome({
        workspaceId,
        channel,
        userMessage: message,
        ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
        contactId,
        intent,
        confidence: actionsList.length > 0 ? 0.85 : 0.55,
        actions: actionsList.map((action) => ({
          toolName: action.tool,
          success: unifiedAgentActionSucceeded(action.result),
          result: action.result,
        })),
      });

      return {
        actions: actionsList,
        ...(draftedReply !== undefined ? { response: draftedReply } : {}),
        intent,
        confidence: actionsList.length > 0 ? 0.85 : 0.55,
      };
    }

    // 4. Ask the LLM to verbalize only; code-native actions enter via predecidedActions.
    let llmResponse: OpenAI.Chat.ChatCompletion;
    try {
      await this.planLimits.ensureTokenBudget(params.workspaceId);
      const openai = this.openai;
      if (!openai) {
        const error = new Error();
        error.message = UNIFIED_AGENT_PROVIDER_CONFIG_REQUIRED;
        throw error;
      }
      llmResponse = await chatCompletionWithFallback(
        openai,
        {
          model: this.primaryBrainModel,
          messages,
          temperature: 0.82,
          top_p: 0.9,
        },
        this.fallbackBrainModel,
      );
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : typeof err === 'string' ? err : 'unknown';
      this.logger.error(`OpenAI agent processing failed, using fallback: ${msg}`);
      return this.response.buildFallbackResult(message);
    }
    if (!llmResponse) {
      return this.response.buildFallbackResult(message);
    }
    const firstChoice = llmResponse.choices[0];
    if (!firstChoice) {
      return this.response.buildFallbackResult(message);
    }
    await this.planLimits
      .trackAiUsage(params.workspaceId, llmResponse.usage?.total_tokens ?? 500)
      .catch(() => {});

    const assistantMessage = firstChoice.message;
    const actionsList = await executeUnifiedAgentToolCalls({
      assistantMessage,
      actions: this.actions,
      logger: this.logger,
      workspaceId,
      contactId,
      phone,
      executeTool: this.executeToolAction.bind(this),
      ...(params.allowedTools !== undefined ? { allowedTools: params.allowedTools } : {}),
      ...(context !== undefined ? { context } : {}),
    });

    // 6. Extract intent, confidence, and compose final reply
    const intent = this.response.extractIntent(actionsList, message);
    const confidence = this.response.calculateConfidence(actionsList, llmResponse);
    const draftedReply = await this.response.composeWriterReply(
      this.openai,
      this.writerModel,
      this.fallbackWriterModel,
      {
        workspaceId,
        customerMessage: message,
        assistantDraft: assistantMessage.content,
        actions: actionsList,
        historyTurns,
      },
    );

    await this.agentRuntime?.recordTurnOutcome({
      workspaceId,
      channel,
      userMessage: message,
      ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
      contactId,
      intent,
      confidence,
      actions: actionsList.map((action) => ({
        toolName: action.tool,
        success: unifiedAgentActionSucceeded(action.result),
        result: action.result,
      })),
    });

    return {
      actions: actionsList,
      ...(draftedReply !== undefined ? { response: draftedReply } : {}),
      intent,
      confidence,
    };
  }

  /**
   * Public API: execute a single named tool directly.
   */
  async executeTool(
    tool: string,
    args: ToolArgs,
    ctx: { workspaceId: string; contactId?: string; phone?: string },
  ): Promise<unknown> {
    return this.executeToolAction(
      ctx.workspaceId,
      ctx.contactId || '',
      ctx.phone || '',
      tool,
      args,
    );
  }

  /** Build quoted reply plan (delegates to response service). */
  async buildQuotedReplyPlan(params: {
    workspaceId: string;
    contactId?: string;
    phone: string;
    draftReply: string;
    customerMessages: Array<{ content: string; quotedMessageId: string }>;
  }): Promise<Array<{ quotedMessageId: string; text: string }>> {
    return this.response.buildQuotedReplyPlan(
      this.openai,
      this.writerModel,
      this.fallbackWriterModel,
      this.planLimits,
      params,
    );
  }

  // ───────── tool router ─────────

  private async executeToolAction(
    workspaceId: string,
    contactId: string,
    phone: string,
    tool: string,
    args: ToolArgs,
    context?: UnknownRecord,
  ): Promise<unknown> {
    return executeUnifiedAgentToolAction({
      prisma: this.prisma,
      auditService: this.auditService,
      actions: this.actions,
      logger: this.logger,
      ...(this.agentRuntime !== undefined ? { agentRuntime: this.agentRuntime } : {}),
      ...(this.riskGate !== undefined ? { riskGate: this.riskGate } : {}),
      openai: this.openai,
      primaryBrainModel: this.primaryBrainModel,
      fallbackBrainModel: this.fallbackBrainModel,
      workspaceId,
      contactId,
      phone,
      tool,
      args,
      ...(context !== undefined ? { context } : {}),
    });
  }
}

import { forEachSequential } from '../common/async-sequence';
import type { ActionEntry, PredecidedAction, ToolArgs } from './unified-agent.types';
import { getBrainCapabilityRisk } from './brain-capability-policy';
import type { BrainCapabilityRisk } from './brain-capability-policy';

type UnknownRecord = Record<string, unknown>;

type RiskClassLabel = 'R1' | 'R2' | 'R3';

interface CapabilityBlockResult {
  blocked: true;
  reason: 'capability_not_allowed';
  riskClass: RiskClassLabel;
  approvalRequired: boolean;
  escalation: string;
  safeNextStep: string;
  rollback: string;
}

function mapBrainRiskToRiskClass(risk: BrainCapabilityRisk): RiskClassLabel {
  if (risk === 'critical') return 'R3';
  if (risk === 'high') return 'R2';
  return 'R1';
}

function buildCapabilityBlockResult(tool: string): CapabilityBlockResult {
  const risk = getBrainCapabilityRisk(tool);
  const riskClass = mapBrainRiskToRiskClass(risk);

  const approvalRequired = riskClass !== 'R1';
  const escalation =
    riskClass === 'R3'
      ? 'human_operator_required'
      : riskClass === 'R2'
        ? 'workspace_owner_review'
        : 'none';
  const safeNextStep =
    tool === 'create_payment_link'
      ? 'redirect_to_manual_checkout'
      : tool === 'send_message'
        ? 'respond_without_tool'
        : 'use_allowed_alternative';

  return {
    blocked: true,
    reason: 'capability_not_allowed',
    riskClass,
    approvalRequired,
    escalation,
    safeNextStep,
    rollback: 'not_executed',
  };
}

function isCapabilityBlockResult(value: unknown): value is CapabilityBlockResult {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const record = value as Record<string, unknown>;
  return record.blocked === true && record.reason === 'capability_not_allowed';
}

export type PredecidedToolExecutor = (
  workspaceId: string,
  contactId: string,
  phone: string,
  tool: string,
  args: ToolArgs,
  context?: UnknownRecord,
) => Promise<unknown>;

export type PredecidedActionLogger = (
  workspaceId: string,
  contactId: string,
  tool: string,
  args: ToolArgs,
  result: unknown,
) => Promise<unknown>;

export async function executePredecidedAgentActions(input: {
  allowedTools?: string[];
  contactId: string;
  context?: UnknownRecord;
  executeTool: PredecidedToolExecutor;
  logAutopilotEvent: PredecidedActionLogger;
  phone: string;
  predecidedActions: PredecidedAction[];
  workspaceId: string;
}): Promise<ActionEntry[]> {
  const allowed = typeof input.allowedTools === 'undefined' ? null : new Set(input.allowedTools);
  const actionsList: ActionEntry[] = [];

  await forEachSequential(input.predecidedActions, async (action) => {
    if (allowed && !allowed.has(action.tool)) {
      const blockedResult = buildCapabilityBlockResult(action.tool);
      actionsList.push({
        tool: action.tool,
        args: action.args,
        result: blockedResult,
      });
      await input.logAutopilotEvent(
        input.workspaceId,
        input.contactId,
        action.tool,
        action.args,
        blockedResult,
      );
      return;
    }

    const result = await input.executeTool(
      input.workspaceId,
      input.contactId,
      input.phone,
      action.tool,
      action.args,
      input.context,
    );
    actionsList.push({ tool: action.tool, args: action.args, result });
    await input.logAutopilotEvent(
      input.workspaceId,
      input.contactId,
      action.tool,
      action.args,
      result,
    );
  });

  return actionsList;
}

export function buildPredecidedActionDraft(actions: ActionEntry[]): string {
  if (actions.length === 0) {
    return 'Ação comercial validada: responder com clareza e próximo passo.';
  }

  return actions
    .map((action) => {
      if (isCapabilityBlockResult(action.result)) {
        if (action.tool === 'create_payment_link') {
          return 'Link de pagamento não enviado: ação exige aprovação humana antes de avançar.';
        }
        if (action.tool === 'send_message') {
          return 'Mensagem não enviada: ação fora da política permitida; responder sem ferramenta ou pedir aprovação.';
        }
        return `Ação não executada: ${action.tool} exige ${action.result.escalation}.`;
      }
      if (action.tool === 'send_message') {
        return `Mensagem enviada: ${String(action.args.message || action.args.text || '').trim()}`;
      }
      if (action.tool === 'schedule_followup') {
        return 'Follow-up agendado conforme política comercial.';
      }
      if (action.tool === 'transfer_to_human') {
        return 'Transferência para atendimento humano iniciada.';
      }
      if (action.tool === 'create_payment_link') {
        return 'Link de pagamento preparado e enviado.';
      }
      return `Ação executada: ${action.tool}.`;
    })
    .join(' ');
}

import type OpenAI from 'openai';
import { forEachSequential } from '../common/async-sequence';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { ActionEntry, ToolArgs } from './unified-agent.types';
import type { UnknownRecord } from './unified-agent-message-context.part';

type UnifiedAgentToolCallLogger = {
  warn(message: string): void;
};

function isAllowedTool(toolName: string, allowedTools?: string[]): boolean {
  return !allowedTools || allowedTools.includes(toolName);
}

export async function executeUnifiedAgentToolCalls(params: {
  assistantMessage: OpenAI.Chat.ChatCompletionMessage;
  actions: UnifiedAgentActionsService;
  logger: UnifiedAgentToolCallLogger;
  workspaceId: string;
  contactId: string;
  phone: string;
  allowedTools?: string[];
  context?: UnknownRecord;
  executeTool: (
    workspaceId: string,
    contactId: string,
    phone: string,
    tool: string,
    args: ToolArgs,
    context?: UnknownRecord,
  ) => Promise<unknown>;
}): Promise<ActionEntry[]> {
  const actionsList: ActionEntry[] = [];
  const executeTools = params.context?.executeTools !== false;

  if (!executeTools || !params.assistantMessage.tool_calls?.length) {
    return actionsList;
  }

  await forEachSequential(params.assistantMessage.tool_calls, async (toolCall) => {
    if (toolCall.type !== 'function') {
      return;
    }
    const toolName = toolCall.function.name;
    if (!isAllowedTool(toolName, params.allowedTools)) {
      params.logger.warn(
        `Blocked disallowed agent tool call: workspaceId=${params.workspaceId} tool=${toolName}`,
      );
      const blockedResult = { blocked: true, reason: 'capability_not_allowed' };
      actionsList.push({ tool: toolName, args: {}, result: blockedResult });
      await params.actions.logAutopilotEvent(
        params.workspaceId,
        params.contactId,
        toolName,
        {},
        blockedResult,
      );
      return;
    }
    let toolArgs: Record<string, unknown> = {};
    try {
      toolArgs = JSON.parse(toolCall.function.arguments || '{}');
    } catch {
      params.logger.warn(`Failed to parse tool args for ${toolName}`);
    }
    const result = await params.executeTool(
      params.workspaceId,
      params.contactId,
      params.phone,
      toolName,
      toolArgs,
      params.context,
    );
    actionsList.push({ tool: toolName, args: toolArgs, result });
    await params.actions.logAutopilotEvent(
      params.workspaceId,
      params.contactId,
      toolName,
      toolArgs,
      result,
    );
  });

  return actionsList;
}

import type { ChatCompletionMessageParam } from 'openai/resources/chat';
import type { PrismaService } from '../prisma/prisma.service';
import type { AgentRuntimeContextService } from './agent-runtime';
import type { AbiBuilderService } from './abi/abi-builder.service';
import { validateAbiPayload } from './abi/abi-validator';
import type { UnifiedAgentContextService } from './unified-agent-context.service';
import type { UnifiedAgentResponseService } from './unified-agent-response.service';

export type UnknownRecord = Record<string, unknown>;

type UnifiedAgentMessageContextLogger = {
  warn(message: string): void;
};

type CurrentUnifiedAgentInput = {
  raw: string;
  channel: string;
  arrivalTimestamp: string;
};

export async function buildUnifiedAgentMessageContext(params: {
  prisma: PrismaService;
  ctx: UnifiedAgentContextService;
  response: UnifiedAgentResponseService;
  logger: UnifiedAgentMessageContextLogger;
  agentRuntime?: AgentRuntimeContextService;
  abiBuilder?: AbiBuilderService;
  allowedTools?: string[];
  workspaceId: string;
  contactId: string;
  phone: string;
  message: string;
  context?: UnknownRecord;
}): Promise<{
  messages: ChatCompletionMessageParam[];
  historyTurns: number;
  channel: string;
}> {
  const { workspaceId, contactId, phone, message, context } = params;

  const [workspace, contact, conversationHistory, products] = await Promise.all([
    params.ctx.getWorkspaceContext(workspaceId),
    params.ctx.getContactContext(workspaceId, contactId, phone),
    params.ctx.getConversationHistory(workspaceId, contactId, 0, phone),
    params.ctx.getProducts(workspaceId),
  ]);

  const productIds = products
    .map((product: UnknownRecord) => {
      const productValue = params.ctx.readRecord(product.value);
      return (
        params.ctx.readOptionalText(productValue.id) || params.ctx.readOptionalText(product.id)
      );
    })
    .filter((productId): productId is string => Boolean(productId));
  let aiConfigs: UnknownRecord[] = [];

  if (productIds.length > 0) {
    try {
      aiConfigs = await params.prisma.productAIConfig.findMany({
        take: 50,
        where: { productId: { in: productIds } },
        select: {
          id: true,
          productId: true,
          tone: true,
          persistenceLevel: true,
          messageLimit: true,
          customerProfile: true,
          positioning: true,
          objections: true,
          salesArguments: true,
        },
      });
    } catch {
      /* ProductAIConfig may not exist yet */
    }
  }

  const compressedContext = await params.ctx.buildAndPersistCompressedContext(
    workspaceId,
    contactId,
    phone,
    contact,
  );
  const tacticalHint = params.ctx.buildLeadTacticalHint({
    leadName: params.ctx.isRecord(contact) ? params.ctx.readText(contact.name).trim() : '',
    currentMessage: message,
    conversationHistory,
  });
  const channel = params.ctx.readText(context?.channel, 'whatsapp');
  const agentRuntimeContext = params.agentRuntime
    ? await params.agentRuntime.buildContext({
        workspaceId,
        channel,
        message,
        contactId,
        ...(params.allowedTools !== undefined ? { allowedTools: params.allowedTools } : {}),
      })
    : { systemPromptBlock: '' };
  const systemPrompt = [
    params.ctx.buildSystemPrompt(workspace, products, aiConfigs),
    agentRuntimeContext.systemPromptBlock,
  ].join('\n\n');
  const stylePolicy = params.response.buildReplyStyleInstruction(
    message,
    conversationHistory.length,
  );
  const contactData: Record<string, unknown> = params.ctx.isRecord(contact) ? contact : {};
  const contactName = params.ctx.readText(contactData.name).trim() || phone;
  const contactSentiment = params.ctx.readText(contactData.sentiment).trim() || 'NEUTRAL';
  const leadScore = params.ctx.readText(contactData.leadScore, '0');
  const tagNames = params.ctx.readTagList(contactData.tags);
  const currentInput = {
    raw: message,
    channel,
    arrivalTimestamp: new Date().toISOString(),
  };
  const cognitiveState = await buildCognitiveState({
    abiBuilder: params.abiBuilder,
    currentInput,
    logger: params.logger,
  });

  return {
    channel,
    historyTurns: conversationHistory.length,
    messages: [
      ...conversationHistory,
      {
        role: 'user',
        content: JSON.stringify({
          cognitiveState,
          runtimeContext: {
            workspaceProductContext: systemPrompt,
            compressedMemory: compressedContext || null,
            additionalContext: context ? formatPromptValue(context) : '',
            tacticalHint: tacticalHint || 'responder com clareza, valor concreto e próximo passo.',
            responsePolicy: stylePolicy,
          },
          contact: {
            name: contactName,
            sentiment: contactSentiment,
            leadScore,
            tags: tagNames,
          },
          currentInput,
        }),
      },
    ],
  };
}

async function buildCognitiveState(params: {
  abiBuilder?: AbiBuilderService;
  currentInput: CurrentUnifiedAgentInput;
  logger: UnifiedAgentMessageContextLogger;
}): Promise<Record<string, unknown>> {
  let cognitiveState: Record<string, unknown> = {
    abiStatus: params.abiBuilder ? 'unavailable_or_invalid' : 'builder_not_injected',
    audience: 'public',
    perceptionSnapshot: { channel: params.currentInput.channel },
  };

  if (!params.abiBuilder) {
    return cognitiveState;
  }

  const abiResult = await params.abiBuilder.build({
    audience: 'public',
    currentInput: params.currentInput,
    perceptionSnapshot: {
      channel: params.currentInput.channel,
    },
  });

  if (abiResult.status !== 'ok') {
    params.logger.warn(
      `ABI build failed: ${abiResult.reason}, using structured unified agent fallback`,
    );
    return cognitiveState;
  }

  const validation = validateAbiPayload(abiResult.abi);

  if (validation.status === 'FAIL') {
    params.logger.warn(
      `ABI validation failed: ${JSON.stringify(validation.issues)}, using structured unified agent fallback`,
    );
    return cognitiveState;
  }

  cognitiveState = abiResult.abi as unknown as Record<string, unknown>;
  return cognitiveState;
}

function formatPromptValue(value: unknown): string {
  if (value === null) {
    return 'null';
  }
  if (Array.isArray(value)) {
    return `[${value.map(formatPromptValue).join(',')}]`;
  }
  if (typeof value === 'object') {
    const record = value as Record<string, unknown>;
    return `{${Object.keys(record)
      .sort()
      .map((key) => `${key}:${formatPromptValue(record[key])}`)
      .join(',')}}`;
  }
  if (typeof value === 'string') {
    return `"${value.replaceAll('\\', '\\\\').replaceAll('"', '\\"')}"`;
  }
  if (typeof value === 'number' || typeof value === 'boolean' || typeof value === 'bigint') {
    return String(value);
  }
  if (typeof value === 'undefined') {
    return 'undefined';
  }
  return Object.prototype.toString.call(value);
}

import type OpenAI from 'openai';
import type { AuditService } from '../audit/audit.service';
import type { PrismaService } from '../prisma/prisma.service';
import type { AgentRuntimeContextService } from './agent-runtime';
import type { RiskGateService } from './risk-class/risk-gate.service';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { ToolArgs } from './unified-agent.types';
import type { UnknownRecord } from './unified-agent-message-context.part';

type UnifiedAgentToolLogger = {
  log(message: string, extra?: Record<string, unknown>): void;
  warn(message: string): void;
  error(message: string): void;
};

export async function executeUnifiedAgentToolAction(params: {
  prisma: PrismaService;
  auditService: AuditService;
  actions: UnifiedAgentActionsService;
  logger: UnifiedAgentToolLogger;
  agentRuntime?: AgentRuntimeContextService;
  riskGate?: RiskGateService;
  openai: OpenAI | null;
  primaryBrainModel: string;
  fallbackBrainModel: string;
  workspaceId: string;
  contactId: string;
  phone: string;
  tool: string;
  args: ToolArgs;
  context?: UnknownRecord;
}): Promise<unknown> {
  const { workspaceId, contactId, phone, tool, args, context } = params;
  params.logger.log(`Executing tool: ${tool}`, { args });
  const envelope = buildAgentToolEnvelope(params.agentRuntime, {
    workspaceId,
    toolName: tool,
  });

  switch (tool) {
    case 'send_message':
      return params.actions.actionSendMessage(workspaceId, phone, args, context);
    case 'send_product_info':
      return params.actions.actionSendProductInfo(workspaceId, phone, args, context);
    case 'create_payment_link':
      return executePaymentLinkTool(params);
    case 'update_lead_status':
      return params.actions.actionUpdateLeadStatus(workspaceId, contactId, args);
    case 'add_tag':
      return params.actions.actionAddTag(workspaceId, contactId, args);
    case 'schedule_followup':
      return params.actions.actionScheduleFollowup(workspaceId, contactId, phone, args, context);
    case 'transfer_to_human':
      return params.actions.actionTransferToHuman(workspaceId, contactId, args, context);
    case 'search_knowledge_base':
      return params.actions.actionSearchKnowledgeBase(workspaceId, args);
    case 'trigger_flow':
      return params.actions.actionTriggerFlow(workspaceId, phone, args);
    case 'log_event':
      return params.actions.actionLogEvent(workspaceId, contactId, args);
    case 'send_media':
      return params.actions.actionSendMedia(workspaceId, phone, args, context);
    case 'send_document':
      return params.actions.actionSendDocument(workspaceId, phone, args, context);
    case 'send_voice_note':
      return params.actions.actionSendVoiceNote(workspaceId, phone, args, context);
    case 'send_audio':
      return params.actions.actionSendAudio(workspaceId, phone, args, context);
    case 'transcribe_audio':
      return params.actions.actionTranscribeAudio(workspaceId, args);
    case 'create_product':
      return params.actions.actionCreateProduct(workspaceId, args);
    case 'update_product':
      return params.actions.actionUpdateProduct(workspaceId, args);
    case 'get_product_plans':
      return params.actions.getProductPlans(params.actions.str(args.productId));
    case 'get_product_ai_config':
      return params.actions.getProductAIConfig(params.actions.str(args.productId));
    case 'get_product_reviews':
      return params.actions.getProductReviews(params.actions.str(args.productId));
    case 'get_product_urls':
      return params.actions.getProductUrls(params.actions.str(args.productId));
    case 'validate_coupon':
      return params.actions.validateCoupon(
        params.actions.str(args.productId),
        params.actions.str(args.code),
      );
    case 'create_flow':
      return params.actions.actionCreateFlow(workspaceId, args);
    case 'update_workspace_settings':
      return params.actions.actionUpdateWorkspaceSettings(workspaceId, args);
    case 'create_broadcast':
      return params.actions.actionCreateBroadcast(workspaceId, args, context);
    case 'get_analytics':
      return params.actions.actionGetAnalytics(workspaceId, args);
    case 'configure_ai_persona':
      return params.actions.actionConfigureAIPersona(workspaceId, args);
    case 'toggle_autopilot':
      return params.actions.actionToggleAutopilot(workspaceId, args);
    case 'create_flow_from_description':
      return params.actions.actionCreateFlowFromDescription(
        workspaceId,
        args,
        params.openai,
        params.primaryBrainModel,
        params.fallbackBrainModel,
      );
    case 'connect_whatsapp':
      return params.actions.actionConnectWhatsApp(workspaceId, args);
    case 'import_contacts':
      return params.actions.actionImportContacts(workspaceId, args);
    case 'generate_sales_funnel':
      return params.actions.actionGenerateSalesFunnel(workspaceId, args);
    case 'schedule_campaign':
      return params.actions.actionScheduleCampaign(workspaceId, args);
    case 'get_workspace_status':
      return params.actions.actionGetWorkspaceStatus(workspaceId, args);
    case 'update_billing_info':
      return params.actions.actionUpdateBillingInfo(workspaceId, args);
    case 'get_billing_status':
      return params.actions.actionGetBillingStatus(workspaceId);
    case 'change_plan':
      return params.actions.actionChangePlan(workspaceId, args);
    case 'apply_discount':
      return executeDiscountTool(params);
    case 'handle_objection':
      return params.actions.actionHandleObjection(workspaceId, contactId, phone, args, context);
    case 'qualify_lead':
      return params.actions.actionQualifyLead(workspaceId, contactId, phone, args, context);
    case 'schedule_meeting':
      return params.actions.actionScheduleMeeting(workspaceId, contactId, phone, args, context);
    case 'anti_churn_action':
      return params.actions.actionAntiChurn(workspaceId, contactId, phone, args, context);
    case 'reactivate_ghost':
      return params.actions.actionReactivateGhost(workspaceId, contactId, phone, args, context);
    default:
      params.logger.warn(`Unknown tool: ${tool}`);
      return { success: false, error: 'Unknown tool', policyEnvelope: envelope };
  }
}

export function unifiedAgentActionSucceeded(result: unknown): boolean {
  if (!result || typeof result !== 'object' || Array.isArray(result)) {
    return false;
  }
  const record = result as Record<string, unknown>;
  return record.success === true || record.ok === true || record.executed === true;
}

async function executePaymentLinkTool(
  params: Parameters<typeof executeUnifiedAgentToolAction>[0],
): Promise<unknown> {
  const paymentAmount = num(params.args.amount);
  if (params.riskGate && paymentAmount > 0) {
    const gateDecision = params.riskGate.gatePaymentAction({
      amountCents: paymentAmount,
      reversible: true,
      target: 'lead',
    });
    if (gateDecision.verdict === 'block') {
      params.logger.error(`R4 BLOCKED: create_payment_link — ${gateDecision.reason}`);
      return {
        success: false,
        blocked: true,
        riskClass: gateDecision.classification.class,
        error: gateDecision.reason,
      };
    }
    if (gateDecision.verdict === 'warn') {
      params.logger.warn(
        `Risk gate: payment ${gateDecision.classification.class} — ${gateDecision.reason}`,
      );
    }
  }

  const result = await params.actions.actionCreatePaymentLink(
    params.workspaceId,
    params.phone,
    params.args,
    params.context,
  );

  try {
    await params.prisma.$transaction(
      async (tx) => {
        await params.auditService.logWithTx(tx, {
          workspaceId: params.workspaceId,
          action: 'AGENT_DISPATCHED_PAYMENT_LINK',
          resource: 'UnifiedAgent',
          resourceId: params.contactId,
          details: { tool: params.tool, phone: params.phone },
        });
      },
      { isolationLevel: 'ReadCommitted' },
    );
  } catch (auditError: unknown) {
    const auditMsg =
      auditError instanceof Error
        ? auditError.message
        : typeof auditError === 'string'
          ? auditError
          : 'unknown';
    params.logger.warn(`Audit dispatch log failed: ${auditMsg}`);
  }

  return result;
}

async function executeDiscountTool(
  params: Parameters<typeof executeUnifiedAgentToolAction>[0],
): Promise<unknown> {
  if (params.riskGate) {
    const gateDecision = params.riskGate.gateDiscountOffer({
      amountCents: 0,
      reversible: true,
      target: 'lead',
    });
    if (gateDecision.verdict === 'block') {
      params.logger.error(`R4 BLOCKED: apply_discount — ${gateDecision.reason}`);
      return {
        success: false,
        blocked: true,
        riskClass: gateDecision.classification.class,
        error: gateDecision.reason,
      };
    }
    if (gateDecision.verdict === 'warn') {
      params.logger.warn(
        `Risk gate: discount ${gateDecision.classification.class} — ${gateDecision.reason}`,
      );
    }
  }

  return params.actions.actionApplyDiscount(
    params.workspaceId,
    params.contactId,
    params.phone,
    params.args,
    params.context,
  );
}

function num(v: unknown, fb = 0): number {
  const n = Number(v);
  return Number.isFinite(n) ? Math.round(n) : fb;
}

function buildAgentToolEnvelope(
  agentRuntime: AgentRuntimeContextService | undefined,
  params: { workspaceId: string; toolName: string },
): { id: string; toolName: string; allowed: boolean } {
  return (
    agentRuntime?.buildToolEnvelope(params) ?? {
      id: 'agent-runtime-unavailable',
      toolName: params.toolName,
      allowed: true,
    }
  );
}
